import math
def priority(task, state, q0=10.0, f0=0.25, c=1.0, g=1.0, m=4.0, k=2.0, s=0.5, b=0.5):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    ratio = wait / est
    congested = (state.queue_len >= q0) or (state.free <= f0 * max(state.capacity, 1e-6))
    if congested:
        urgent = (ratio >= c) or (wait >= g * mean_est)
    else:
        urgent = (ratio >= c)
    if task.tenant == 'premium' and slack <= s * est:
        urgent = True
    guard = 1e6 if urgent else 0.0
    if task.tenant == 'premium':
        pos = max(0.0, slack)
        base = m / est * math.exp(-pos / (k * mean_est))
    else:
        base = 1.0 / est
    if congested:
        base += b * wait / (est * est)
    return guard + base  # tuned (q0=9.78,f0=0.118,c=0.324,g=0.322,m=1.82,k=3.47,s=0.205,b=0.604)

