def priority(task, state, c=2.0, abs_c=1.5, d=0.5, p=1.0, q=1.0, g=1e6, fit=1e5, mem_w=0.2):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    age = max(0.0, state.now - task.release)
    ratio = age / est
    load = state.queue_work / max(state.capacity, 1e-6)
    mem = max(task.resource_need, 1e-6)
    cap = max(state.capacity, 1e-6)
    c = max(c, 1e-6)
    abs_c = max(abs_c, 1e-6)
    p = max(p, 1e-6)
    cap_age = abs_c * mean / max(1.0 + d * load, 1e-6)
    if task.tenant == 'premium':
        slack = task.due - state.now - est
        if slack < 0.0:
            score = 4.0 * g + q * (-slack) / max(mean, 1e-6)
        elif slack <= p * mean + c * est:
            score = 3.0 * g + (p * mean + c * est - slack) / max(mean, 1e-6)
        else:
            if ratio >= c or age >= cap_age:
                score = g + age + 1.0 / est
            else:
                score = 1.0 / est
    else:
        if ratio >= c or age >= cap_age:
            score = g + age + 1.0 / est
        else:
            score = 1.0 / est
    if mem <= state.free:
        score += fit
    else:
        score -= mem_w * mem / cap
    return score

import math
def priority(task, state, cp=0.8, c=1.0, a=0.4, b=1.0, k=1.5, m=5.0, h=4.0, g=0.2):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    mean = max(state.mean_est, 1e-6)
    cap = max(state.capacity, 1e-6)
    free_ratio = max(0.0, min(1.0, state.free / cap))
    mem_pen = 1.0 / (1.0 + g * (1.0 - free_ratio) * task.resource_need / max(state.free + task.resource_need, 1e-6))

    w = max(task.weight, 1e-6)
    if task.tenant == 'premium':
        slack = task.due - state.now - est
        if slack <= 0.0:
            return 1e12 + b * wait + w / est
        if ratio >= cp or slack <= k * mean:
            return 1e9 + b * wait + m * w / est * mem_pen
        return m * w / est * math.exp(-max(0.0, slack) / max(k * mean, 1e-6)) * (1.0 + a * ratio) * mem_pen
    else:
        horizon = h * mean * (1.0 + math.log1p(max(state.queue_len, 0)))
        slack_v = task.release + horizon - state.now - est
        if slack_v <= 0.0 or ratio >= c:
            return 1e8 + b * wait + 1.0 / est
        return (1.0 / est) * math.exp(-max(0.0, slack_v) / max(k * mean, 1e-6)) * (1.0 + a * ratio) * mem_pen  # tuned (cp=0.767,c=0.607,a=0.346,b=0.312,k=1.51,m=1.8,h=10.6,g=0.154)

def priority(task, state, guard=2.0, big=1e6, a=1.0, b=0.5, c=3.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    wait = max(0.0, state.now - task.release)
    ratio = wait / est
    if task.tenant == 'premium':
        if slack <= guard * est:
            return big + (state.now - task.due) / est + ratio
        return -(task.due - state.now) / est
    else:
        score = (a + b * ratio + max(0.0, ratio - c) ** 2) / est
        if ratio >= c:
            score += big
        return score
